using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Auth;using MediDesk.Common.Contracts.Catalog;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/admin/users")][Authorize(Policy=PermissionPolicies.UsersView)]public sealed class UsersAdminController(IUserAdminService s,IAuthService auth):ControllerBase{[HttpGet]public async Task<ActionResult<PagedResponse<UserAdminDto>>>Get([FromQuery]UserAdminQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct));[HttpPost][Authorize(Policy=PermissionPolicies.UsersAdd)]public async Task<IActionResult>Create(CreateUserAdminRequest r,CancellationToken ct){try{return Ok(await auth.SignupAsync(new SignupRequest(r.FullName,r.Email,r.Password),ct));}catch(InvalidOperationException e){return Conflict(new ProblemDetails{Title=e.Message});}}[HttpPut("{id:long}")][Authorize(Policy=PermissionPolicies.UsersEdit)]public async Task<IActionResult>Update(long id,UpdateUserAdminRequest r,CancellationToken ct)=>await s.UpdateAsync(id,r,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct)?NoContent():Conflict();}}

